mapper.select:
select id, season_id as seasonId, event_team_id as eventTeamId, operation_type as operationType,
       target_roster_id as targetRosterId, target_player_id as targetPlayerId, before_value as beforeValue,
       after_value as afterValue, operate_reason as operateReason, effective_time as effectiveTime,
       operator_name as operatorName, create_time as createTime
from basket_tournament_roster_operation_log
where is_delete = 0
and season_id = #{seasonId}
and event_team_id = #{eventTeamId}
and operation_type = #{operationType}
order by create_time desc, id desc
